window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-cd7ef01cd1ba10e7"]={"versions": [{"id": "FIG-cd7ef01cd1ba10e7", "releases": ["R4.1.3", "R4.2.2", "R4.3.1", "R18-10_R4.4.0_R1.5.0", "R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Architektur- und Timing-Spezifikationsdiagramm aus AUTOSAR TPS Timing Extensions zur Veranschaulichung des Komponenten- und Kontrollflusses für Timing Requirement 5. Das Diagramm modelliert eine AUTOSAR Classic Platform Software-Komponente auf VFB-/RTE-Ebene mit zugeordneten internen Ausführungseinheiten und Timing-Vorgaben bezüglich der Aktivierung bzw. Auslösung.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Ignition</strong> (<code>Application Software Component</code>): Anwendungskomponente, dargestellt als grauer Komponentenblock.</li>\n<li><strong>RE</strong> (<code>Runnable Entity</code>): Innerhalb von <code>Ignition</code> gekapselte funktionale Ausführungseinheit (blaue Box mit zentrierter Beschriftung).</li>\n<li><strong>Ports / Interfaces</strong>: Zwei Schnittstellen-Ports an der unteren Begrenzung der Komponente:</li>\n<li>Linker Port mit Pfeil nach oben (symbolisiert einen Input-/Required-Port bzw. Empfang).</li>\n<li>Rechter Port mit Pfeil nach unten (symbolisiert einen Output-/Provided-Port bzw. Senden).</li>\n<li><strong>Triggering constraint for starting runnable entity</strong>: Spezifikationselement/Constraint, das über einen gerichteten Pfeil von außen direkt auf die <code>Runnable Entity</code> (<code>RE</code>) zeigt.</li>\n<li><strong>Legend</strong>: Textueller Legendenblock mit der Auflösung des Akronyms <code>RE</code> zu <code>Runnable Entity</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm stellt die zeitliche Aktivierungsbedingung für die <code>Runnable Entity</code> (<code>RE</code>) dar. Der Kontrollfluss wird durch die externe Aktivierungsvorgabe (<em>Triggering constraint for starting runnable entity</em>) initiiert, welche den Startzeitpunkt bzw. die Auslöseintervalle der <code>RE</code> innerhalb des Komponentenkontrollflusses regelt. Die Ports am unteren Rand indizieren den ein- und ausgehenden Daten- bzw. Signalfluss der Komponente, der mit der Ausführung der Runnable Entity interagiert.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm veranschaulicht ein normatives Timing-Szenario der AUTOSAR Timing Extensions (TPS TimingExtensions) für Ausführungsbedingungen von Runnables. Für Modellierer und Entwickler definiert die Kennzeichnung, dass Auslöse- und Aktivierungszeitpunkte (<code>TriggeringConstraint</code> / Aktivierungsereignisse wie <code>TimingEvent</code> oder datengetriebene Trigger) auf RTE-Ebene semantisch direkt an die Ausführung der jeweiligen <code>RunnableEntity</code> gekoppelt werden müssen.</p>"}, {"id": "FIG-9021e987ce82f338", "releases": ["R19-11", "R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Architektur- und Timing-Spezifikationsdiagramm aus AUTOSAR TPS Timing Extensions zur Veranschaulichung des Komponenten- und Kontrollflusses für Timing Requirement 5. Das Diagramm modelliert eine AUTOSAR Classic Platform Software-Komponente auf VFB-/RTE-Ebene mit zugeordneten internen Ausführungseinheiten und Timing-Vorgaben bezüglich der Aktivierung bzw. Auslösung.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Ignition</strong> (<code>Application Software Component</code>): Anwendungskomponente, dargestellt als grauer Komponentenblock.</li>\n<li><strong>RE</strong> (<code>Runnable Entity</code>): Innerhalb von <code>Ignition</code> gekapselte funktionale Ausführungseinheit (blaue Box mit zentrierter Beschriftung).</li>\n<li><strong>Ports / Interfaces</strong>: Zwei Schnittstellen-Ports an der unteren Begrenzung der Komponente:</li>\n<li>Linker Port mit Pfeil nach oben (symbolisiert einen Input-/Required-Port bzw. Empfang).</li>\n<li>Rechter Port mit Pfeil nach unten (symbolisiert einen Output-/Provided-Port bzw. Senden).</li>\n<li><strong>Triggering constraint for starting runnable entity</strong>: Spezifikationselement/Constraint, das über einen gerichteten Pfeil von außen direkt auf die <code>Runnable Entity</code> (<code>RE</code>) zeigt.</li>\n<li><strong>Legend</strong>: Textueller Legendenblock mit der Auflösung des Akronyms <code>RE</code> zu <code>Runnable Entity</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm stellt die zeitliche Aktivierungsbedingung für die <code>Runnable Entity</code> (<code>RE</code>) dar. Der Kontrollfluss wird durch die externe Aktivierungsvorgabe (<em>Triggering constraint for starting runnable entity</em>) initiiert, welche den Startzeitpunkt bzw. die Auslöseintervalle der <code>RE</code> innerhalb des Komponentenkontrollflusses regelt. Die Ports am unteren Rand indizieren den ein- und ausgehenden Daten- bzw. Signalfluss der Komponente, der mit der Ausführung der Runnable Entity interagiert.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm veranschaulicht ein normatives Timing-Szenario der AUTOSAR Timing Extensions (TPS TimingExtensions) für Ausführungsbedingungen von Runnables. Für Modellierer und Entwickler definiert die Kennzeichnung, dass Auslöse- und Aktivierungszeitpunkte (<code>TriggeringConstraint</code> / Aktivierungsereignisse wie <code>TimingEvent</code> oder datengetriebene Trigger) auf RTE-Ebene semantisch direkt an die Ausführung der jeweiligen <code>RunnableEntity</code> gekoppelt werden müssen.</p>"}], "trans": [{"from": "FIG-cd7ef01cd1ba10e7", "to": "FIG-9021e987ce82f338", "fr": "R18-10_R4.4.0_R1.5.0", "tr": "R19-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-9021e987ce82f338", "to": "FIG-cd7ef01cd1ba10e7", "fr": "R20-11", "tr": "R22-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
